# area: gradual_any
# hypothesis: An Any argument passes an int parameter without a diagnostic while an object argument is rejected, and at runtime passing None through the Any path raises TypeError, so a checker that accepts that path misses a real failure.
from typing import Any, assert_type, reveal_type


def double(n: int) -> int:
    return n * 2


def via_any(v: Any) -> int:
    return double(v)


def via_object(v: object) -> int:
    return double(v)  # expect-error


def roundtrip(v: Any) -> object:
    out: object = v
    return out


reveal_type(via_any(4))
assert_type(roundtrip('kept'), object)
print(via_any(4), via_object(4))
print(roundtrip('kept'))
try:
    print(via_any(None))
except TypeError as exc:
    print('TypeError:', exc)
